using Microsoft.EntityFrameworkCore;

namespace Kpz.Lab2.Data;

/// <summary>Prints SQL generated by EF Core for representative LINQ query shapes.</summary>
public static class EfQuerySqlDemo
{
    public static void Run(KpzDbContext db)
    {
        Console.WriteLine();
        Console.WriteLine("=== EF CORE LINQ TO SQL DEMO ===");

        var filteredTrips = db.Trips
            .AsNoTracking()
            .Where(trip => trip.TripCategoryId == 1 &&
                           trip.Destination.Contains("Kyiv") &&
                           trip.StartDate >= new DateOnly(2026, 10, 1) &&
                           trip.StartDate < new DateOnly(2027, 3, 1))
            .OrderBy(trip => trip.StartDate)
            .ThenBy(trip => trip.TripId);

        PrintQuery(
            "1. Filtering and sorting",
            "FROM Trips; WHERE filters category, destination, and date range; ORDER BY start date and key; entity projection.",
            filteredTrips.ToQueryString());

        var tripList = db.Trips
            .AsNoTracking()
            .OrderBy(trip => trip.StartDate)
            .ThenBy(trip => trip.TripId)
            .Select(trip => new TripListDto(
                trip.TripId,
                trip.TripName,
                trip.Destination,
                trip.StartDate,
                trip.Owner.FullName,
                trip.Category.Name,
                trip.ItineraryItems.Count));

        PrintQuery(
            "2. DTO projection with related values",
            "FROM Trips; joins Users and TripCategories; correlated COUNT for ItineraryItems; selects only DTO columns; ORDER BY date and key.",
            tripList.ToQueryString());

        var relatedTrips = db.Trips
            .AsNoTracking()
            .AsSplitQuery()
            .Include(trip => trip.Owner)
            .Include(trip => trip.Category)
            .Include(trip => trip.ItineraryItems)
                .ThenInclude(item => item.Type)
            .OrderBy(trip => trip.StartDate)
            .ThenBy(trip => trip.TripId);

        PrintQuery(
            "3. Related entity graph with AsSplitQuery",
            "Loads Trips with Users, TripCategories, ItineraryItems, and ItineraryItemTypes. EF emits a fixed set of split SELECTs, not one query per trip.",
            relatedTrips.ToQueryString());

        var bookingGroups = db.Bookings
            .AsNoTracking()
            .Where(booking => booking.Item.Trip.StartDate >= new DateOnly(2026, 10, 1) &&
                              booking.Item.Trip.StartDate < new DateOnly(2027, 3, 1))
            .GroupBy(booking => booking.Item.Trip.Category.Name)
            .Select(group => new
            {
                CategoryName = group.Key,
                BookingCount = group.Count(),
                TotalPrice = group.Sum(booking => booking.Price)
            })
            .OrderByDescending(group => group.TotalPrice)
            .ThenBy(group => group.CategoryName);

        PrintQuery(
            "4. GroupBy with aggregates",
            "FROM Bookings joined through ItineraryItems and Trips to TripCategories; WHERE date range; GROUP BY category; COUNT and SUM; ORDER BY total price.",
            bookingGroups.ToQueryString());

        Console.WriteLine("N+1 check: each query is translated before enumeration; the DTO uses SQL joins/subquery, and the entity graph uses a fixed split-query count.");
        Console.WriteLine("No loop issues a separate database query per returned trip in these examples.");
    }

    private static void PrintQuery(string title, string explanation, string sql)
    {
        Console.WriteLine();
        Console.WriteLine(title);
        Console.WriteLine($"Translation: {explanation}");
        Console.WriteLine(sql);
    }
}
